package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrMockStorage struct {
	storage.Client
	writes int
}

func (m *gsrMockStorage) ReadFile(ctx context.Context, bucket, object string) ([]byte, string, error) {
	// Return valid empty JSON and ignore ctx so ReadFile itself doesn't abort early.
	return []byte(`{}`), "etag", nil
}

func (m *gsrMockStorage) WriteFile(ctx context.Context, bucket, object string, data []byte, ifMatch string) error {
	m.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Cancel the context immediately before the call

	mock := &gsrMockStorage{Client: storage.NewMemoryClient()}
	s := &Store{
		Storage: mock,
		Bucket:  "test-bucket",
	}

	_, _ = s.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact {
		return c
	})

	if mock.writes >= maxWriteRetries {
		t.Fatalf("Store.Mutate(ctx) = %d writes, want < %d (should abort early on a cancelled context)", mock.writes, maxWriteRetries)
	}
}

